    const previousSequenceValue = own(previousProgress, 'progressSequence');
    const previousSequence = Number.isSafeInteger(previousSequenceValue) &&
        previousSequenceValue >= 0 ? previousSequenceValue : 0;
    if (previousSequence >= 1_000_000) return state;
    const sameStage = own(previousProgress, 'stage') === phase;
    const previousCompleted = sameStage
        ? Math.max(0, Math.min(4096, Math.floor(Number(
            own(previousProgress, 'completed')
        ) || 0))) : 0;
    const previousTotal = sameStage
        ? Math.max(0, Math.min(4096, Math.floor(Number(
            own(previousProgress, 'total')
        ) || 0))) : 0;
    const completed = Math.max(previousCompleted,
        Math.min(eventCompleted, eventTotal || eventCompleted));
    const total = Math.max(previousTotal, eventTotal, completed);
    const timestamp = Math.max(0, Math.floor(Number(now) || 0));
