        const titleAndLevel = canonicalSections.filter(section =>
            section.title === title && section.level === level);
        if (titleAndLevel.length === 1) return titleAndLevel;
        const titleOnly = canonicalSections.filter(section => section.title === title);
        if (titleOnly.length === 1) return titleOnly;
