        const sectionId = String(section?.sectionId || '');
        const explicit = articleNavigatorState.analysisSectionSelection.has(sectionId)
            ? articleNavigatorState.analysisSectionSelection.get(sectionId) === true
            : undefined;
        const title = normalizeTitle(section?.title);
        const level = Math.max(1, Number(section?.level) || ancestorTitles.length + 1);
        const candidates = semanticSignatureCandidates(title, level, ancestorTitles);
        const canonicalSection = candidates.length === 1 ? candidates[0] : null;
        if (canonicalSection) mappedCanonicalSectionIds.add(canonicalSection.sectionId);
        let selected = explicit;
        if (selected === undefined) selected = canonicalSelection(canonicalSection);
        if (selected === undefined && inheritedSelection !== undefined) {
            selected = inheritedSelection;
        }
        if (selected === undefined && !canonicalSelectionCustomized) {
            const inferredKind = inferKind(title);
            if (inferredKind) selected = defaultArticleAnalysisSectionSelection(inferredKind);
        }
        const targets = Array.isArray(section?.paragraphTargets)
