function filterParagraphsForArticleAnalysis(paragraphs = []) {
    // Navigation stores canonical section IDs; HTML extraction keeps its original
    // IDs for grounding and rendering. Join by source identity, never heading text.
    const canonical = typeof getCanonicalArticleSnapshot === 'function'
        ? getCanonicalArticleSnapshot()?.paragraphs : [];
    const sectionsBySource = new Map();
    for (const paragraph of Array.isArray(canonical) ? canonical : []) {
        const sourceKey = String(paragraph?.sourceKey || '');
        const sectionId = String(paragraph?.sectionId || '');
        if (!sourceKey || !sectionId) continue;
        if (!sectionsBySource.has(sourceKey)) sectionsBySource.set(sourceKey, new Set());
        sectionsBySource.get(sourceKey).add(sectionId);
    }
    return (Array.isArray(paragraphs) ? paragraphs : []).filter(paragraph => {
        const matches = sectionsBySource.get(String(paragraph.paragraphId || ''));
        if (matches?.size === 1) {
            const [canonicalSectionId] = matches;
            if (articleNavigatorState.analysisSectionSelection.has(canonicalSectionId)) {
                return articleNavigatorState.analysisSectionSelection.get(canonicalSectionId) === true;
            }
        }
        return articleAnalysisSectionSelected(paragraph.sectionId, paragraph.sectionKind);
    });
}

function setArticleAnalysisSectionSelection(sectionIds, selected) {
    const ids = (Array.isArray(sectionIds) ? sectionIds : [sectionIds])
        .map(String).filter(Boolean);
    ids.forEach(sectionId => {
        articleNavigatorState.analysisSectionSelection.set(sectionId, selected === true);
    });
    const allowedParagraphIds = selectedArticleAnalysisParagraphIds();
    const semanticAnalysisScope = currentNativePdfSemanticAnalysisScope();
    if (lastRegexHighlightRequest?.categories) {
        highlighter.applyHighlight(
            lastRegexHighlightRequest.categories,
            lastRegexHighlightRequest.mode || 'word',
            {
                allowedParagraphIds,
                semanticAnalysisScope,
                analysisModeId: lastRegexHighlightRequest.analysisModeId
            }
        );
    }
    if (lastLlmAnalysis?.rawAnalysis && Array.isArray(lastLlmAnalysis.paragraphs)) {
        renderLlmAnalysis(
            lastLlmAnalysis.rawAnalysis,
            lastLlmAnalysis.paragraphs,
            lastLlmAnalysis.threshold || 0.8,
            lastLlmAnalysis.extractionDiagnostics
        );
    }
    scheduleArticleWorkspaceArtifactsSave({ immediate: true });
    scheduleCurrentArticleArchiveSave();
    return {
        success: true,
        snapshot: buildArticleWorkspaceSnapshot(),
        // allowedParagraphIds includes both canonical IDs and raw aliases.
        selectedParagraphCount: getCanonicalArticleSnapshot().paragraphs.filter(paragraph =>
            articleAnalysisSectionSelected(paragraph.sectionId, paragraph.sectionKind)
        ).length
    };
}
