async function loadZoteroSnapshotPluginCss() {
    try {
        const cssResponse = await fetch(chrome.runtime.getURL('content.css'), {
            cache: 'no-store'
        });
        if (!cssResponse.ok) throw new Error(`CONTENT_CSS_HTTP_${cssResponse.status}`);
        let css = await cssResponse.text();
        try {
            const fontResponse = await fetch(
                chrome.runtime.getURL('vendor/phosphor/Phosphor.woff2'),
                { cache: 'no-store' }
            );
            if (fontResponse.ok) {
                const fontDataUrl = encodeSnapshotImageDataUrl(
                    new Uint8Array(await fontResponse.arrayBuffer()),
                    fontResponse.headers.get('content-type') || 'font/woff2'
                );
                css = css.replace(
                    /url\((['"]?)(?:chrome-extension:\/\/[^/"'\s]+\/)?vendor\/phosphor\/Phosphor\.woff2\1\)/g,
                    `url("${fontDataUrl}")`
                );
            }
        } catch (_) {}
        return css;
    } catch (error) {
        console.warn('Brevess：未能读取快照样式，使用最小兼容样式', error);
        return `
          html[data-sci-reader-single-column="true"] :is(
            .c-article-main-column,.c-article-body,#article-body,.article-body,
            .article__body,[data-test="article-body"],[data-aa-name="article-body"]
          ){float:none!important;width:100%!important;max-width:100%!important}
          .sci-highlight,.sci-llm-highlight{border-bottom:3px solid}
        `;
    }
}

function serializeZoteroSnapshotDoctype() {
    const doctype = document.doctype;
    if (!doctype?.name) return '<!doctype html>';
    let serialized = `<!DOCTYPE ${doctype.name}`;
    if (doctype.publicId) {
        serialized += ` PUBLIC "${doctype.publicId.replace(/"/g, '&quot;')}"`;
    }
    if (doctype.systemId) {
        serialized += `${doctype.publicId ? '' : ' SYSTEM'} "${
            doctype.systemId.replace(/"/g, '&quot;')
        }"`;
    }
    return `${serialized}>`;
}

function buildEnhancedArticleSnapshotHtml(options = {}) {
    const article = options.article || {};
    const annotations = options.annotations ||
        currentManualDocument?.record?.annotations || [];
    const embeddedImageByElement = options.embeddedImageByElement || new Map();
    const annotationById = new Map(
        annotations.map(annotation => [String(annotation.annotationId || ''), annotation])
    );
    const outputDocument = document.implementation.createHTMLDocument(
        String(article.title || document.title || 'Offline article')
    );
    outputDocument.documentElement.lang = document.documentElement.lang || 'en';
    outputDocument.documentElement.setAttribute('data-sci-reader-single-column', 'true');
    outputDocument.documentElement.setAttribute('data-sci-reader-snapshot', 'faithful-v1');
    outputDocument.documentElement.setAttribute('data-sci-snapshot-scope', 'article-root-v2');
    outputDocument.documentElement.setAttribute(
        'data-sci-publisher-family',
        String(article.publisherFamily || 'generic')
    );

    outputDocument.head.replaceChildren();
    const charset = outputDocument.createElement('meta');
    charset.setAttribute('charset', 'utf-8');
    const policy = outputDocument.createElement('meta');
    policy.httpEquiv = 'Content-Security-Policy';
    policy.content = "default-src 'none'; img-src data:; style-src 'unsafe-inline'; " +
        "font-src data:; connect-src 'none'; media-src 'none'; frame-src 'none'; " +
        "object-src 'none'; base-uri 'none'; form-action 'none'";
    const title = outputDocument.createElement('title');
    title.textContent = String(article.title || document.title || 'Offline article');
    const style = outputDocument.createElement('style');
    style.id = 'sci-reader-snapshot-style';
    style.textContent = [
        String(options.pluginCss || ''),
        zoteroSnapshotStyle(),
        zoteroFaithfulSnapshotStyle()
    ].join('\n');
    const generator = outputDocument.createElement('meta');
    generator.name = 'generator';
    generator.content = `Brevess article-root snapshot; ${
        options.exportedAt || new Date().toISOString()
    }`;
    outputDocument.head.append(charset, policy, title, style, generator);

    outputDocument.body.replaceChildren();
    const shell = outputDocument.createElement('main');
    shell.className = 'sci-snapshot-shell';
    const snapshotHeader = outputDocument.createElement('header');
    snapshotHeader.className = 'sci-snapshot-header';
    const kicker = outputDocument.createElement('p');
    kicker.className = 'sci-snapshot-kicker';
    kicker.textContent = 'Brevess offline article';
    const heading = outputDocument.createElement('h1');
    heading.textContent = String(article.title || document.title || 'Offline article');
    const metadata = outputDocument.createElement('p');
    metadata.className = 'sci-snapshot-meta';
    metadata.textContent = [
        String(article.publisherFamily || '').trim(),
        String(options.exportedAt || new Date().toISOString()).trim()
    ].filter(Boolean).join(' · ');
    const sourceUrl = absoluteSnapshotUrl(article.url || effectiveArticlePageUrl());
    if (/^https?:\/\//i.test(sourceUrl)) {
        const separator = outputDocument.createTextNode(' · ');
        const sourceLink = outputDocument.createElement('a');
        sourceLink.href = sourceUrl;
        sourceLink.rel = 'noopener noreferrer';
        sourceLink.textContent = 'Original article';
        metadata.append(separator, sourceLink);
    }
    snapshotHeader.append(kicker, heading, metadata);
    shell.appendChild(snapshotHeader);

    const articleContainer = outputDocument.createElement('section');
    articleContainer.className = 'sci-snapshot-article';
    const liveRoot = resolveZoteroSnapshotArticleRoot();
    if (liveRoot) {
        const clonedRoot = outputDocument.importNode(liveRoot, true);
        cleanZoteroSnapshotArticleRoot(
            liveRoot,
            clonedRoot,
            embeddedImageByElement,
            annotationById
        );
        articleContainer.appendChild(clonedRoot);
    } else {
        // A login/paywall shell is not a paper. If no trustworthy article root
        // exists, rebuild a text-only document from the already extracted
        // canonical paragraphs instead of persisting publisher account UI.
        let previousSection = '';
        (Array.isArray(article.paragraphs) ? article.paragraphs : []).forEach(paragraph => {
            const section = String(
                paragraph.displaySectionTitle || paragraph.sectionTitle || ''
            ).trim();
            if (section && section !== previousSection) {
                const sectionHeading = outputDocument.createElement('h2');
                sectionHeading.textContent = section;
                articleContainer.appendChild(sectionHeading);
                previousSection = section;
            }
            const text = String(paragraph.displayText || paragraph.text || '').trim();
            if (!text) return;
            const body = outputDocument.createElement('p');
            body.textContent = text;
            articleContainer.appendChild(body);
        });
        if (!articleContainer.childElementCount) {
            const unavailable = outputDocument.createElement('p');
            unavailable.textContent =
                'The article body was not available when this offline snapshot was saved.';
            articleContainer.appendChild(unavailable);
        }
    }
    shell.appendChild(articleContainer);
    appendZoteroSnapshotNavigation(outputDocument, articleContainer);
    appendSnapshotAnnotationAppendix(shell, annotations);
    outputDocument.body.appendChild(shell);
    return `<!doctype html>\n${outputDocument.documentElement.outerHTML}`;
}

async function collectZoteroSnapshotFigureResources(collected) {
    const embeddedImageByElement = new Map();
    const galleryFigures = [];
    const missingImageFigureIds = [];
    let embeddedImageCount = 0;
    let embeddedImageBytes = 0;
    for (const [figureIndex, record] of collected.records.entries()) {
        const sourceFigure = collected.inventoryById.get(record.figureId);
        const images = sourceFigure
            ? await collectExportFigureImages(sourceFigure, figureIndex) : [];
        if (!images.length) {
            missingImageFigureIds.push(record.figureId || record.figureLabel);
            continue;
        }
        const galleryFigure = {
            figureId: record.figureId,
            figureLabel: record.figureLabel,
            caption: record.caption,
            images: []
        };
        images.forEach((image, imageIndex) => {
            const anchorId = `sci-snapshot-figure-${figureIndex + 1}-image-${imageIndex + 1}`;
            const dataUrl = encodeSnapshotImageDataUrl(image.data, image.contentType);
            const liveImage = sourceFigure.imageElements?.[image.imageElementIndex];
            if (liveImage && !embeddedImageByElement.has(liveImage)) {
                embeddedImageByElement.set(liveImage, {
                    ...image,
                    anchorId,
                    dataUrl
                });
            }
            galleryFigure.images.push({
                ...image,
                liveImage,
                anchorId,
                dataUrl
            });
            record.imageFiles.push(`snapshot.html#${anchorId}`);
            record.images.push({
                path: `snapshot.html#${anchorId}`,
                contentType: image.contentType,
                byteLength: image.byteLength,
                sourceUrl: publicExportSourceUrl(image.sourceUrl),
                requestedSourceUrl: publicExportSourceUrl(image.requestedSourceUrl),
                pixelWidth: image.pixelWidth,
                pixelHeight: image.pixelHeight,
                candidateCount: image.candidateCount,
                qualitySelection: image.qualitySelection,
                displayedWidth: image.displayedWidth,
                displayedHeight: image.displayedHeight
            });
            embeddedImageCount += 1;
            embeddedImageBytes += Number(image.byteLength) || 0;
        });
        galleryFigures.push(galleryFigure);
    }
    return {
        embeddedImageByElement,
        galleryFigures,
        missingImageFigureIds,
        embeddedImageCount,
        embeddedImageBytes
    };
}

async function exportEnhancedSnapshotToZotero() {
    if (typeof SciLLM.buildZoteroFigureNoteHtml !== 'function' ||
        typeof SciLLM.buildZoteroChatNoteHtml !== 'function' ||
        typeof SciLLM.createZipBlob !== 'function') {
        throw new Error('ZOTERO_EXPORT_MODULE_UNAVAILABLE');
    }
    const article = buildArticleWorkspaceSnapshot({ forceRefresh: true, chatLimit: 0 });
    const collected = collectCompleteExportFigures();
    const annotations = currentManualDocument?.record?.annotations || [];
    const exportedAt = new Date().toISOString();
    const imageBundle = await collectZoteroSnapshotFigureResources(collected);
    const sharedNoteInput = {
        title: article.title,
        url: article.url,
        exportedAt,
        figures: collected.records,
        crossFigureLogic: collected.crossFigureLogic,
        chat: article.chat,
        embeddedImageCount: imageBundle.embeddedImageCount
    };
    const figureNoteHtml = SciLLM.buildZoteroFigureNoteHtml(sharedNoteInput);
    const chatNoteHtml = SciLLM.buildZoteroChatNoteHtml(sharedNoteInput);
    const pluginCss = await loadZoteroSnapshotPluginCss();
    const snapshotContent = buildEnhancedArticleSnapshotHtml({
        article,
        annotations,
        exportedAt,
        pluginCss,
        embeddedImageByElement: imageBundle.embeddedImageByElement
    });
    const payload = {
        title: article.title,
        url: article.url,
        snapshotContent,
        figureNoteHtml,
        chatNoteHtml
    };
    let response = null;
    let directError = null;
    try {
        response = await chrome.runtime.sendMessage({
            type: 'ZOTERO_IMPORT_ENHANCED_SNAPSHOT',
            payload
        });
        if (response?.success && response.data?.imported) {
            return {
                success: true,
                imported: true,
                embeddedImageCount: imageBundle.embeddedImageCount,
                embeddedImageBytes: imageBundle.embeddedImageBytes,
                missingImageFigureIds: imageBundle.missingImageFigureIds,
                ...response.data
            };
        }
        directError = {
            code: response?.error?.code || 'ZOTERO_IMPORT_FAILED',
            message: response?.error?.message || 'Zotero 未接受增强快照'
        };
    } catch (error) {
        directError = {
            code: error?.code || 'ZOTERO_UNAVAILABLE',
            message: error?.message || 'Zotero 不可用'
        };
    }

    const fallbackMetadata = {
        schemaVersion: 1,
        exportKind: 'sci-reader-zotero-enhanced-snapshot',
        extensionVersion: chrome.runtime.getManifest?.().version || '',
        exportedAt,
        title: article.title,
        url: article.url,
        publisherFamily: article.publisherFamily,
        directImportError: directError,
        figureCount: collected.records.length,
        embeddedImageCount: imageBundle.embeddedImageCount,
        embeddedImageBytes: imageBundle.embeddedImageBytes,
        missingImageFigureIds: imageBundle.missingImageFigureIds,
        chatTurnCount: Number(article.chat?.totalTurns) || 0,
        manualAnnotationCount: annotations.length,
        zoteroChildNoteCount: 2
    };
    const fallbackZip = await SciLLM.createZipBlob([
        { path: 'snapshot.html', data: snapshotContent },
        {
            path: 'notes/SCI-Reader-Figure-Interpretation.html',
            data: figureNoteHtml
        },
        {
            path: 'notes/SCI-Reader-Fulltext-QA.html',
            data: chatNoteHtml
        },
        { path: 'metadata.json', data: SciLLM.exportJson(fallbackMetadata) },
        {
            path: 'README.md',
            data: SciLLM.buildZoteroFallbackReadme({
                title: article.title,
                url: article.url
            })
        }
    ]);
    const filename = `${SciLLM.sanitizeExportFilename(
        article.title, 'SCI-article'
    )}-Zotero-enhanced-snapshot.zip`;
    downloadContentExportBlob(fallbackZip, filename);
    return {
        success: true,
        imported: false,
        fallbackDownloaded: true,
        filename,
        embeddedImageCount: imageBundle.embeddedImageCount,
        embeddedImageBytes: imageBundle.embeddedImageBytes,
        missingImageFigureIds: imageBundle.missingImageFigureIds,
        directError
    };
}

async function maybeAutoAnalyzeWithLLM() {
    try {
        const response = await chrome.runtime.sendMessage({ type: 'LLM_GET_SETTINGS' });
        if (response?.success && response.data.effectiveMode === 'llm' && response.data.settings.autoAnalyze) {
            await prepareArticleProfileWithLLM({ auto: true });
        }
    } catch (error) {
        console.warn('Brevess: 自动 LLM 分析未启动', error.message);
    }
}

// 创建高亮器实例
const highlighter = new SciPaperHighlighter();

function ensureHighlightSourceVisibilityStyle() {
    let style = document.getElementById('sci-highlight-source-visibility-style');
    if (style) return style;
    style = document.createElement('style');
    style.id = 'sci-highlight-source-visibility-style';
    style.textContent = `
      html[data-sci-show-regex="false"] .pdf-native-regex-hit,
      html[data-sci-show-regex="false"] .pdf-native-annotation-hit[data-source="regex"],
      html[data-sci-show-regex="false"] .sci-highlight[data-source="regex"],
      html[data-sci-show-regex="false"] .sci-manual-highlight[data-source="regex"] {
        background: transparent !important; border-color: transparent !important;
        box-shadow: none !important; text-decoration: none !important;
      }
      html[data-sci-show-llm="false"] .sci-llm-highlight:not([data-source="semantic"]) {
        background: transparent !important; border-color: transparent !important;
        box-shadow: none !important; text-decoration: none !important;
      }
      html[data-sci-show-manual="false"] .pdf-native-annotation-hit:not([data-source="regex"]),
      html[data-sci-show-manual="false"] .pdf-native-semantic-chat-hit,
      html[data-sci-show-manual="false"] .sci-manual-highlight:not([data-source="regex"]) {
        background: transparent !important; border-color: transparent !important;
        box-shadow: none !important; text-decoration: none !important;
      }
    `;
    (document.head || document.documentElement).appendChild(style);
    return style;
}

function setHighlightSourceVisibility(sources = []) {
    visibleHighlightSources = new Set(
        (Array.isArray(sources) ? sources : [])
            .filter(source => ['regex', 'llm', 'manual'].includes(source))
    );
    ensureHighlightSourceVisibilityStyle();
    ['regex', 'llm', 'manual'].forEach(source => {
        document.documentElement.dataset[
            `sciShow${source[0].toUpperCase()}${source.slice(1)}`
        ] = String(visibleHighlightSources.has(source));
    });
    return [...visibleHighlightSources];
}

setHighlightSourceVisibility([...visibleHighlightSources]);

// 监听来自popup的消息
function publicCrossFigureMechanismProgress() {
    const operation = crossFigureLogicState.operation;
    const binding = operation?.binding;
    const progress = crossFigureLogicState.progress;
    if (!operation || !binding || !progress || !operation.epoch) return null;
    return Object.freeze({
        taskType: 'crossFigure',
        phase: progress.stage,
        status: crossFigureLogicState.status,
        operationId: operation.operationId,
        operationEpoch: operation.epoch,
        evidenceFirstVersions: operation.evidenceFirstVersions,
        documentId: binding.documentId,
        workspaceId: binding.workspaceId,
        workspaceGeneration: binding.workspaceGeneration,
        workspaceLifecycle: binding.workspaceLifecycle,
        baseWorkspaceRevision: binding.baseWorkspaceRevision,
        mechanismChainFingerprint: binding.mechanismChainFingerprint,
        completed: progress.completed,
        total: progress.total,
        progressSequence: Number.isSafeInteger(progress.progressSequence)
            ? progress.progressSequence : 0,
        heartbeatAt: Number.isSafeInteger(progress.heartbeatAt)
            ? progress.heartbeatAt : 0,
        elapsedSeconds: Math.max(0, Math.min(3600, Math.floor(
            (Date.now() - operation.startedAt) / 1000
        ))),
        errorCode: String(crossFigureLogicState.audit?.code || '').slice(0, 80)
    });
}

function publishCrossFigureMechanismProgress() {
    const progress = publicCrossFigureMechanismProgress();
    if (!progress) return false;
    chrome.runtime.sendMessage({ type: 'LLM_OPERATION_PROGRESS', progress }).catch(() => {});
    return true;
}

function applyAndPublishCrossFigureMechanismProgress(value) {
    if (!crossFigureLogicRuntime?.operation ||
        crossFigureLogicRuntime.operation.cancelled === true) return false;
    const next = applyCrossFigureMechanismProgress(crossFigureLogicState, value, Date.now());
    if (next === crossFigureLogicState) return false;
    crossFigureLogicState = next;
    crossFigureLogicRuntime.operation.epoch = next.operation.epoch;
    publishCrossFigureMechanismProgress();
    return true;
}

function publishPublicLlmOperationProgress(value = {}) {
    const phase = String(value.phase || '').trim().toLowerCase();
    if (!/^[a-z][a-z0-9_]{1,63}$/.test(phase)) return;
    const taskType = String(value.taskType || value.route?.taskType || '')
        .trim().slice(0, 40);
    const progress = {
        phase,
        taskType,
        elapsedSeconds: Math.max(0, Math.min(3600,
            Math.floor(Number(value.elapsedSeconds) || 0))),
        timeoutSeconds: Math.max(0, Math.min(3600,
            Math.ceil((Number(value.timeoutMs) || 0) / 1000))),
        completed: Math.max(0, Math.floor(Number(
            value.completedFigures ?? value.completedParagraphs ?? value.completedChunks
        ) || 0)),
        total: Math.max(0, Math.floor(Number(
            value.totalFigures ?? value.totalParagraphs ?? value.totalChunks
        ) || 0)),
        errorCode: /^[A-Z][A-Z0-9_-]{2,80}$/.test(String(value.errorCode || ''))
            ? String(value.errorCode) : ''
    };
    chrome.runtime.sendMessage({ type: 'LLM_OPERATION_PROGRESS', progress }).catch(() => {});
}

function currentFigureLlmProgressBinding() {
    const workspace = currentFigureWorkspaceRefreshBinding();
    return Object.freeze({
        documentIdentity: String(contentDocumentIdentity || ''),
        navigationIdentity: String(contentNavigationIdentity() || ''),
        documentId: String(workspace.documentId || ''),
        workspaceId: String(workspace.workspaceId || ''),
        workspaceGeneration: Number(workspace.workspaceGeneration) || 0,
        workspaceLifecycle: articleWorkspaceLifecycleGeneration
    });
}

function sameFigureLlmProgressOwner(left, right) {
    if (!left || !right ||
        !String(left.documentIdentity || '') ||
        String(left.documentIdentity) !== String(right.documentIdentity || '') ||
        !String(left.navigationIdentity || '') ||
        String(left.navigationIdentity) !== String(right.navigationIdentity || '') ||
        !Number.isSafeInteger(left.workspaceLifecycle) ||
        left.workspaceLifecycle !== right.workspaceLifecycle) return false;
    if (left.documentId && left.documentId !== right.documentId) return false;
    if (left.workspaceId && (
        left.workspaceId !== right.workspaceId ||
        !Number.isSafeInteger(left.workspaceGeneration) ||
        left.workspaceGeneration < 1 ||
        left.workspaceGeneration !== right.workspaceGeneration
    )) return false;
    return true;
}

function bindFigureOperationProgress(operation) {
    if (!operation || !isCurrentFigureOperation(operation) || operation.cancelled === true) {
        return null;
    }
    const current = currentFigureLlmProgressBinding();
    const previous = operation.progressBinding;
    if (previous && !sameFigureLlmProgressOwner(previous, current)) return null;
    operation.progressBinding = Object.freeze({
        ...current,
        documentId: String(previous?.documentId || current.documentId || ''),
        workspaceId: String(previous?.workspaceId || current.workspaceId || ''),
        workspaceGeneration: Number(previous?.workspaceId
            ? previous.workspaceGeneration : current.workspaceGeneration) || 0
    });
    return operation.progressBinding;
}

function isCurrentFigureLlmProgress(progress = {}) {
    const active = figureOperationState.active;
    const operationId = crossFigureMechanismOwnData(progress, 'operationId');
    const workspaceLifecycle = crossFigureMechanismOwnData(
        progress, 'workspaceLifecycle'
    );
    if (!active || active.cancelled === true || typeof operationId !== 'string' ||
        operationId !== active.operationId ||
        !Number.isSafeInteger(workspaceLifecycle) ||
        workspaceLifecycle !== active.workspaceLifecycle ||
        workspaceLifecycle !== articleWorkspaceLifecycleGeneration ||
        !sameFigureLlmProgressOwner(
            active.progressBinding,
            currentFigureLlmProgressBinding()
        )) return false;

    const current = currentFigureLlmProgressBinding();
    const documentId = crossFigureMechanismOwnData(progress, 'documentId');
    const workspaceId = crossFigureMechanismOwnData(progress, 'workspaceId');
    const workspaceGeneration = crossFigureMechanismOwnData(
        progress, 'workspaceGeneration'
    );
    if (documentId !== undefined && (
        typeof documentId !== 'string' || !documentId || documentId !== current.documentId
    )) return false;
    if (workspaceId !== undefined && (
        typeof workspaceId !== 'string' || !workspaceId || workspaceId !== current.workspaceId
    )) return false;
    if (workspaceGeneration !== undefined && (
        !Number.isSafeInteger(workspaceGeneration) || workspaceGeneration < 1 ||
        workspaceGeneration !== current.workspaceGeneration
    )) return false;
    return true;
}

function applyAndPublishFigureProgressEvent(progress = {}) {
    if (!isCurrentFigureLlmProgress(progress)) return null;
    const applied = applyFigureProgressEvent(progress);
    if (!applied) return null;
    publishPublicLlmOperationProgress(progress);
    return applied;
}

chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
    const expectedNavigationIdentity = String(request?.expectedNavigationIdentity || '');
    const expectedDocumentIdentity = String(request?.expectedDocumentIdentity || '');
    if (expectedNavigationIdentity &&
        expectedNavigationIdentity !== contentNavigationIdentity()) {
        sendResponse({
            success: false,
            error: {
                code: 'TAB_MESSAGE_NAVIGATION_STALE',
                message: 'TAB_MESSAGE_NAVIGATION_STALE'
            }
        });
        return;
    }
    if (expectedDocumentIdentity && expectedDocumentIdentity !== contentDocumentIdentity) {
        sendResponse({
            success: false,
            error: {
                code: 'TAB_MESSAGE_NAVIGATION_STALE',
                message: 'TAB_MESSAGE_NAVIGATION_STALE'
            }
        });
        return;
    }
    if (request.action === 'openSemanticFind') {
        if (sender.id !== chrome.runtime.id || !globalThis.__brevessSemanticFind) {
            sendResponse({ success: false });
            return;
        }
        globalThis.__brevessSemanticFind.open();
        sendResponse({ success: true });
    } else if (request.action === 'semanticFindProgress') {
        if (sender.id === chrome.runtime.id) globalThis.__brevessSemanticFind?.handleProgress(request);
        sendResponse({ success: true });
    } else if (request.type === 'ABBREVIATION_MEMORY_CHANGED') {
        globalAbbreviationMemory = SciLLM.normalizeGlobalAbbreviationMemory(request.memory);
        globalAbbreviationMemoryPromise = null;
        sendResponse({ success: true });
    } else if (request.action === 'getContentScriptRevision') {
        sendResponse({
            contentRevision: document.documentElement.dataset.sciLlmContentRevision || '',
            navigationIdentity: contentNavigationIdentity(),
            documentIdentity: contentDocumentIdentity
        });
    } else if (request.action === 'warmArticleIndex') {
        const expectedUrl = String(request.expectedUrl || '');
        const liveUrl = contentNavigationIdentity();
        if (expectedUrl && expectedUrl !== liveUrl) {
            sendResponse({ success: true, scheduled: false, ignored: true });
            return;
        }
        scheduleArticlePreindex('warm-article-index');
        sendResponse({ success: true, scheduled: true });
    } else if (request.action === 'llmFigureWorkspaceCommitGuard') {
        sendResponse(validateFigureWorkspaceCommitGuardRequest(request));
    } else if (request.action === 'validatePdfFigureProductionContext') {
        validatePdfFigureProductionContextRequest(request, sender)
            .then(sendResponse)
            .catch(() => sendResponse({
                success: false,
                code: 'PDF_FIGURE_CONTEXT_STALE'
            }));
        return true;
    } else if (request.action === 'getPdfWorkspaceState') {
        const controlState = document.getElementById('pdfReaderControl')?.dataset?.state || '';
        sendResponse({
            success: true,
            pdfMode: globalThis.SciLLM?.isPdfReaderUrl?.(location.href) === true,
            ready: document.documentElement.dataset.pdfWorkspaceReady === 'true',
            nativeReadable: Boolean(activeNativePdfStructure()?.paragraphs?.length &&
                document.getElementById('pdfNativeViewer')?.dataset?.state === 'ready'),
            textCoverage: activeNativePdfStructure()?.diagnostics?.textCoverage || null,
            rendered: document.documentElement.dataset.pdfWorkspaceRendered === 'true',
            indexed: document.documentElement.dataset.pdfWorkspaceIndexed === 'true',
            state: controlState || 'loading',
            readerUrl: location.href,
            sourceUrl: effectiveArticlePageUrl()
        });
    } else if (request.action === 'prepareSidePanelShortcutScope') {
        sendResponse({
            success: true,
            documentIdentity: contentDocumentIdentity,
            navigationIdentity: contentNavigationIdentity()
        });
    } else if (request.action === 'setSidePanelShortcutScope') {
        sendResponse({
            success: true,
            enabled: applySidePanelShortcutScopeMessage(request)
        });
    } else if (request.action === 'setHighlightSourceVisibility') {
        sendResponse({
            success: true,
            visibleSources: setHighlightSourceVisibility(request.visibleSources)
        });
    } else if (request.action === 'llmFigureCheckpoint') {
        const checkpoint = request.checkpoint && typeof request.checkpoint === 'object'
            ? request.checkpoint : {};
        if (!Number.isInteger(checkpoint.workspaceLifecycle) ||
            checkpoint.workspaceLifecycle !== articleWorkspaceLifecycleGeneration) {
            sendResponse({
                success: false,
                code: 'FIGURE_CHECKPOINT_BINDING_INVALID'
            });
            return;
        }
        applyPrivateFigureCheckpoint(checkpoint)
            .then(receipt => sendResponse({
                success: true,
                savedPanelCount: receipt.savedPanelCount
            }))
            .catch(error => sendResponse({
                success: false,
                code: error.code || 'FIGURE_CHECKPOINT_PERSIST_FAILED'
            }));
        return true;
    } else if (request.action === 'llmAnalysisProgress') {
        const progress = crossFigureMechanismOwnData(request, 'progress') || {};
        const completedChunkCount = Number.isFinite(Number(progress.completedChunks))
            ? Math.max(0, Math.floor(Number(progress.completedChunks)))
            : 0;
        const totalChunkCount = Number.isFinite(Number(progress.totalChunks))
            ? Math.max(0, Math.floor(Number(progress.totalChunks)))
            : 0;
        const chunkProgressLabel = totalChunkCount > 0
            ? `${Math.min(completedChunkCount + 1, totalChunkCount)}/${totalChunkCount}`
            : '';
        if (Number.isInteger(progress.workspaceLifecycle) &&
            progress.workspaceLifecycle !== articleWorkspaceLifecycleGeneration) {
            sendResponse({ success: true, ignored: true, reason: 'STALE_WORKSPACE_LIFECYCLE' });
            return;
        }
        const mechanismProgress =
            crossFigureMechanismOwnData(progress, 'taskType') === 'crossFigure' ||
            CROSS_FIGURE_MECHANISM_STAGES.has(String(
                crossFigureMechanismOwnData(progress, 'phase') || ''
            )) || String(crossFigureMechanismOwnData(progress, 'operationId') || '')
                .startsWith('mechanism:');
        if (mechanismProgress) {
            const accepted = applyAndPublishCrossFigureMechanismProgress(progress);
            sendResponse({
                success: true,
                ignored: !accepted,
                ...(!accepted ? { reason: 'STALE_OR_UNBOUND_MECHANISM_PROGRESS' } : {})
            });
            return;
        }
        if (progress.taskType === 'chat' || String(progress.phase || '').startsWith('chat_')) {
            const accepted = applyArticleChatProgress(progress);
            if (accepted) publishPublicLlmOperationProgress(progress);
            sendResponse({
                success: true,
                ignored: !accepted,
                ...(!accepted ? { reason: 'STALE_OR_UNBOUND_CHAT_PROGRESS' } : {})
            });
            return;
        }
        if (progress.taskType === 'figure' || progress.figureId) {
            const figureProgress = applyAndPublishFigureProgressEvent(progress);
            if (figureProgress) {
                showLlmPageStatus(formatFigureProgressMessage(figureProgress),
                    figureProgress.failed ? 'error' : undefined);
            }
            sendResponse({
                success: true,
                ignored: !figureProgress,
                ...(!figureProgress ? { reason: 'STALE_OR_UNBOUND_FIGURE_PROGRESS' } : {})
            });
            return;
        }
        publishPublicLlmOperationProgress(progress);
        if (progress.phase === 'token_limit_retry') {
            showLlmPageStatus('模型不接受当前输出长度，正在降低令牌上限后重试…');
        } else if (progress.phase === 'output_token_retry') {
            showLlmPageStatus('输出长度不足，正在增加令牌上限后重试…');
        } else if (progress.phase === 'output_compact_retry') {
            showLlmPageStatus('输出被截断，正在改用紧凑 JSON 格式重试…');
        } else if (String(progress.phase || '').startsWith('review_')) {
            if (progress.phase === 'review_chunk_checkpoint') {
                (Array.isArray(progress.checkpointSummaries)
                    ? progress.checkpointSummaries : []).forEach(item => {
                    const paragraphId = String(item?.paragraphId || '').trim();
                    if (paragraphId) standaloneReviewParagraphSummaries.set(paragraphId, item);
                });
                articleNavigatorState.summariesVisible = true;
                scheduleArticleWorkspaceArtifactsSave({ immediate: true });
            }
            const completedParagraphs = Number(progress.completedParagraphs) || 0;
            const totalParagraphs = Number(progress.totalParagraphs) ||
                reviewOutlineStatus.totalParagraphs;
            const completedChunks = Number(progress.completedChunks) || 0;
            const totalChunks = Number(progress.totalChunks) || reviewOutlineStatus.totalChunks;
            let message = '正在生成逐段摘要（' + completedParagraphs + '/' + totalParagraphs + '）…';
            if (progress.phase === 'review_retry') {
                const seconds = Math.max(1, Math.ceil((Number(progress.waitMs) || 0) / 1000));
                const stageName = progress.stage === 'reduce' ? '全局组织综合' : '逐段摘要';
                message = progress.errorCode === 'INVALID_RESPONSE'
                    ? stageName + '格式不符合要求，正在自动纠正，' + seconds + ' 秒后重试…'
                    : stageName + '暂时繁忙，' + seconds + ' 秒后重试…';
            } else if (progress.phase === 'review_split') {
                message = progress.errorCode === 'INVALID_RESPONSE'
                    ? '当前返回格式仍不稳定，已自动拆小并继续（' +
                        completedParagraphs + '/' + totalParagraphs + '）…'
                    : '当前摘要分块过大或超时，已自动拆分并继续（' +
                        completedParagraphs + '/' + totalParagraphs + '）…';
            } else if (progress.phase === 'review_reduce') {
                message = '逐段摘要已完成，正在综合全文组织逻辑…';
            } else if (progress.phase === 'review_complete') {
                message = progress.globalSynthesisAvailable
                    ? '综述结构大纲已完成' : '逐段大纲已完成，全局组织综合暂不可用';
            }
            updateReviewOutlineStatus({
                phase: progress.phase,
                completedParagraphs,
                totalParagraphs,
                completedChunks,
                totalChunks,
                message,
                globalSynthesisAvailable: progress.phase === 'review_complete'
                    ? Boolean(progress.globalSynthesisAvailable)
                    : reviewOutlineStatus.globalSynthesisAvailable
            });
            showLlmPageStatus(message,
                progress.phase === 'review_complete' && !progress.globalSynthesisAvailable
                    ? 'error' : undefined);
        } else if (progress.phase === 'figure_retry') {
            const seconds = Math.max(1, Math.ceil((Number(progress.waitMs) || 0) / 1000));
            updateFigureAnalysisStatus({
                phase: 'retrying',
                currentFigure: (Number(progress.completedFigures) || 0) + 1,
                totalFigures: Number(progress.totalFigures) || figureAnalysisStatus.totalFigures,
                figureLabel: progress.figureLabel || figureAnalysisStatus.figureLabel,
                message: (progress.figureLabel || '当前 Figure') + ' 请求暂时失败，' +
                    seconds + ' 秒后自动重试第 ' + (Number(progress.attempt) || 1) + ' 次'
            });
            showLlmPageStatus(
                progress.figureLabel + ' 请求暂时失败，' + seconds + ' 秒后自动重试…'
            );
        } else if (progress.phase === 'figure_fallback') {
            updateFigureAnalysisStatus({
                phase: 'fallback',
                currentFigure: (Number(progress.completedFigures) || 0) + 1,
                totalFigures: Number(progress.totalFigures) || figureAnalysisStatus.totalFigures,
                figureLabel: progress.figureLabel || figureAnalysisStatus.figureLabel,
                message: (progress.figureLabel || '当前 Figure') +
                    ' 的视觉输入不受模型支持，正改用图注与正文继续'
            });
            showLlmPageStatus(
                progress.figureLabel + ' 的模型不支持当前视觉输入，已改用图注与正文继续解读…'
            );
        } else if (progress.phase === 'figure') {
            updateFigureAnalysisStatus({
                phase: 'analyzing',
                currentFigure: Number(progress.completedFigures) || figureAnalysisStatus.currentFigure,
                totalFigures: Number(progress.totalFigures) || figureAnalysisStatus.totalFigures,
                completedFigures: Number(progress.completedFigures) || figureAnalysisStatus.completedFigures,
                figureLabel: progress.figureLabel || figureAnalysisStatus.figureLabel,
                message: (progress.figureLabel || '当前 Figure') + ' 已完成'
            });
            showLlmPageStatus(
                '逐图解读 ' + progress.completedFigures + '/' + progress.totalFigures +
                '：' + progress.figureLabel + ' 已完成…'
            );
        } else if (progress.phase === 'retry') {
            const waitSeconds = Math.max(1, Math.ceil((Number(progress.waitMs) || 0) / 1000));
            const reason = progress.errorCode === 'RATE_LIMITED'
                ? '请求频率受限'
                : progress.errorCode === 'PROVIDER_UNAVAILABLE'
                    ? '模型服务暂时过载'
                    : '模型连接暂时不稳定';
            showLlmPageStatus(
                `${reason}，${waitSeconds} 秒后自动重试第 ${progress.attempt} 次` +
                (chunkProgressLabel ? `（${chunkProgressLabel}）…` : '…')
            );
        } else if (progress.phase === 'split') {
            const reason = progress.errorCode === 'REQUEST_TIMEOUT'
                ? '当前分块分析超时'
                : progress.errorCode === 'PROVIDER_UNAVAILABLE'
                    ? '模型持续繁忙'
                    : progress.errorCode === 'OUTPUT_TRUNCATED'
                        ? '当前分块输出过长'
                        : '当前分块需要降载';
            showLlmPageStatus(
                `${reason}，已自动拆分为更小分块并继续分析` +
                (totalChunkCount > 0
                    ? `（已完成 ${completedChunkCount}/${totalChunkCount}）…`
                    : '…')
            );
        } else if (progress.phase === 'paragraph_checkpoint') {
            renderProgressiveLlmChunk(progress);
            showLlmPageStatus(
                `当前段落已完成并保存（${progress.checkpointedAnnotations || 0} 条候选），正在继续分析…`
            );
        } else if (progress.phase === 'chunk_checkpoint') {
            renderProgressiveLlmChunk(progress);
            showLlmPageStatus(
                `当前小块结果已渲染（${progress.checkpointedAnnotations || 0} 条候选），正在继续下一块…`
            );
        } else if (progress.phase === 'complete') {
            showLlmPageStatus(totalChunkCount > 0
                ? `LLM 已完成 ${completedChunkCount}/${totalChunkCount} 个分块…`
                : 'LLM 分析已完成。');
        } else {
            showLlmPageStatus(chunkProgressLabel
                ? `LLM 正在分析 ${chunkProgressLabel} 个分块…`
                : 'LLM 正在分析正文分块…');
        }
        sendResponse({ success: true });
    } else if (request.action === 'getReviewOutlineStatus') {
        sendResponse({
            success: true,
            status: getPublicReviewOutlineStatus(),
            hasOutline: Boolean(lastReviewOutline),
            outline: lastReviewOutline ? {
                paragraphCount: lastReviewOutline.paragraphCount,
                globalSynthesisAvailable: lastReviewOutline.globalSynthesisAvailable,
                reviewSubtype: lastReviewOutline.reviewSubtype
            } : null
        });
    } else if (request.action === 'showReviewOutline') {
        if (lastReviewOutline) {
            sendResponse({ success: true, shown: true, outline: lastReviewOutline });
        } else {
            sendResponse({ success: true, shown: false, reason: 'NO_REVIEW_OUTLINE' });
        }
    } else if (request.action === 'getArticleWorkspaceSnapshot') {
        Promise.resolve().then(async () => {
            await ensureGlobalAbbreviationMemory().catch(() => globalAbbreviationMemory);
            const snapshot = await readArticleWorkspaceSnapshot(request);
            maintainArticleStructureObserverAfterWorkspaceSnapshot();
            // This request is read-only. Scheduling a full checkpoint here
            // used to overwrite a valid on-disk chat/index.json with an empty
            // in-memory index before local restoration had a chance to run.
            // Every real mutation already schedules its own checkpoint.
            return withCurrentPdfSemanticNavigation({
                success: true,
                snapshot
            });
        }).then(sendResponse).catch(error => {
            sendResponse({ success: false, error: error.message, code: error.code,
                retryable: error.code === 'ARTICLE_PAGE_LOADING' });
        });
    } else if (request.action === 'getArticleAbbreviations') {
        ensureGlobalAbbreviationMemory()
            .catch(() => globalAbbreviationMemory)
            .then(() => sendResponse({
                success: true,
                abbreviations: getPublicArticleAbbreviationSnapshot({
                    forceRefresh: request.forceRefresh === true
                })
            }))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'addArticleAbbreviation') {
        addCurrentArticleAbbreviation(request.entry)
            .then(abbreviations => sendResponse({ success: true, abbreviations }))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'removeArticleAbbreviation') {
        removeCurrentArticleAbbreviation(request.abbreviation)
            .then(abbreviations => sendResponse({ success: true, abbreviations }))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'updateArticleAbbreviationTranslations') {
        updateCurrentArticleAbbreviationTranslations(
            Array.isArray(request.translations) ? request.translations : []
        )
            .then(abbreviations => sendResponse({ success: true, abbreviations }))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'ensureArticleWorkspace') {
        ensureCurrentArticleWorkspace({ forceRefresh: request.forceRefresh === true })
            .then(workspace => sendResponse(createArticleWorkspaceEnsureResponse(workspace)))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'saveArticleWorkspaceBaseline') {
        persistArticleWorkspaceBaseline()
            .then(result => sendResponse({ success: true, ...result }))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'syncSupplementalFigureInventoryToParent') {
        syncParsedSupplementalInventoryToParent(request.parsedDocument || null)
            .then(result => sendResponse({ success: true, ...result }))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'createArticleLogicMap') {
        createArticleLogicMap({ blank: request.blank === true })
            .then(sendResponse)
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'RESEARCH_LOGIC_MAP_CREATE_FAILED'
            }));
    } else if (request.action === 'updateArticleParagraphNote') {
        updateArticleParagraphNote(request)
            .then(sendResponse)
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'PARAGRAPH_NOTE_SAVE_FAILED'
            }));
    } else if (request.action === 'updateFigureWorkspaceDraft') {
        mutateFigureWorkspaceDraftForTarget(request)
            .then(sendResponse)
            .catch(error => sendResponse(publicFigureWorkspaceDraftFailure(error)));
    } else if (request.action === 'restoreFigureWorkspaceModelValue') {
        restoreFigureWorkspaceModelValueForTarget(request)
            .then(sendResponse)
            .catch(error => sendResponse(publicFigureWorkspaceDraftFailure(error)));
    } else if (request.action === 'restoreMechanismNetworkDraft') {
        restoreMechanismNetworkForTarget(request)
            .then(sendResponse)
            .catch(error => sendResponse(publicFigureWorkspaceDraftFailure(error)));
    } else if (request.action === 'flushFigureWorkspaceDraft') {
        flushFigureWorkspaceDraftForTarget(request)
            .then(sendResponse)
            .catch(error => sendResponse(publicFigureWorkspaceDraftFailure(error)));
    } else if (request.action === 'updateFigureAnalysisResult') {
        updateFigureAnalysisResultEdits(
            request.figureId,
            request.analysisDepth,
            request.result
        ).then(sendResponse)
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'FIGURE_RESULT_EDIT_SAVE_FAILED'
            }));
    } else if (request.action === 'restoreFigureAnalysisResult') {
        restoreFigureAnalysisResult(
            request.figureId,
            request.analysisDepth
        ).then(sendResponse)
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'FIGURE_RESULT_EDIT_RESTORE_FAILED'
            }));
    } else if (request.action === 'saveArticleWorkspaceNow') {
        saveCurrentArticleWorkspaceNow(request.operationId)
            .then(sendResponse)
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'ARTICLE_WORKSPACE_SAVE_FAILED'
            }));
    } else if (request.action === 'saveArticleWorkspaceUiState') {
        articleWorkspaceSidePanelUiState = request.uiState && typeof request.uiState === 'object'
            ? { ...request.uiState } : null;
        persistWorkspaceAssetCheckpoint('ui/state.json', {
            navigator: {
                activeTab: articleNavigatorState.activeTab,
                depth: articleNavigatorState.depth,
                summariesVisible: articleNavigatorState.summariesVisible,
                expandedSectionIds: [...articleNavigatorState.expandedSectionIds],
                analysisSectionSelection: Object.fromEntries(
                    articleNavigatorState.analysisSectionSelection
                )
            },
            sidePanel: articleWorkspaceSidePanelUiState
        }).then(() => sendResponse({ success: true }))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'prepareExternalArticleWorkspaceDeletion') {
        sendResponse(prepareExternalArticleWorkspaceDeletion(request.workspaceId));
    } else if (request.action === 'finalizeExternalArticleWorkspaceDeletion') {
        finalizeExternalArticleWorkspaceDeletion(
            request.workspaceId,
            request.workspaceGeneration
        ).then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, matched: true }));
    } else if (request.action === 'freezeArticleWorkspaceWrites') {
        articleWorkspaceSaveFrozen = true;
        clearTimeout(articleWorkspaceSaveTimer);
        clearTimeout(articleArchiveSaveTimer);
        articleWorkspaceSaveTimer = null;
        articleArchiveSaveTimer = null;
        invalidateArticleWorkspaceLifecycle();
        sendResponse({ success: true, frozen: true });
    } else if (request.action === 'applyArticleWorkspaceAssets') {
        applyArticleWorkspaceAssets(request.restore || request)
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'ARTICLE_WORKSPACE_RESTORE_FAILED'
            }));
    } else if (request.action === 'resetArticleWorkspaceState') {
        resetArticleWorkspaceState({ workspaceGeneration: request.workspaceGeneration })
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'getArticleArchiveSnapshot') {
        try {
            sendResponse({ success: true, archive: buildCurrentArticleArchive() });
        } catch (error) {
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'exportPptMaterials') {
        exportPptMaterialBundle()
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'PPT_MATERIAL_EXPORT_FAILED'
            }));
    } else if (request.action === 'exportEnhancedSnapshotToZotero') {
        exportEnhancedSnapshotToZotero()
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'ZOTERO_ENHANCED_SNAPSHOT_EXPORT_FAILED'
            }));
    } else if (request.action === 'applyArticleArchiveSnapshot') {
        applyArticleArchiveSnapshot(request.archive, request.restoreTarget)
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'ARTICLE_WORKSPACE_RESTORE_FAILED'
            }));
    } else if (request.action === 'focusArticleWorkspaceSource') {
        focusArticleWorkspaceSource(request.target || {})
            .then(focusResult => {
                const citationResult = focusResult && typeof focusResult === 'object'
                    ? focusResult : null;
                sendResponse({
                    success: true,
                    focused: citationResult ? citationResult.focused === true : Boolean(focusResult),
                    citationResult
                });
            })
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'armSidePanelRestore') {
        sendResponse({ success: true, armed: armSidePanelRestore() });
    } else if (request.action === 'disarmSidePanelRestore') {
        disarmSidePanelRestore();
        sendResponse({ success: true });
    } else if (request.action === 'getFigureWorkspaceSnapshot') {
        Promise.all((globalThis.__brevessNativePdfFigures?.figures || [])
            .map(figure => restoreNativePdfFigureArtworkSelection(figure).catch(() => undefined)))
            .then(() => sendResponse({ success: true, snapshot: buildFigureWorkspaceSnapshot() }))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'setPdfFigureArtworkPages') {
        if (sender?.id !== chrome.runtime.id) {
            sendResponse({ success: false, code: 'PDF_FIGURE_CONTEXT_STALE' });
        } else setPdfFigureArtworkPages(request)
            .then(sendResponse)
            .catch(error => sendResponse({ success: false, code: error.code, error: error.message }));
    } else if (request.action === 'showArticleNavigator') {
        try {
            sendResponse(showArticleNavigator({ tab: request.tab }));
        } catch (error) {
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'setArticleAnalysisSectionSelection') {
        try {
            sendResponse(setArticleAnalysisSectionSelection(
                request.sectionIds,
                request.selected
            ));
        } catch (error) {
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'getFigureAnalysisStatus') {
        sendResponse({
            success: true,
            status: getPublicFigureAnalysisStatus(),
            analysis: lastFigureAnalysis ? {
                figures: lastFigureAnalysis.figures,
                totalFigures: lastFigureAnalysis.totalFigures,
                failedFigures: lastFigureAnalysis.failedFigures
            } : null
        });
    } else if (request.action === 'prepareManualAnnotations') {
        initializeManualAnnotationUi();
        prepareManualDocument()
            .then(() => {
              const executionProof = manualDocumentExecutionProof();
              sendResponse({
                success: true,
                contentWorldNonce: executionProof.contentWorldNonce,
                documentEpoch: executionProof.documentEpoch,
                documentId: currentManualDocument?.documentId || '',
                documentHash: currentManualDocument?.record?.documentHash || '',
                canonicalUrl: currentManualDocument?.record?.canonicalUrl || '',
                title: currentManualDocument?.record?.title || document.title,
                annotationCount: currentManualDocument?.record?.annotations?.length || 0,
                unresolvedCount: currentManualUnresolved.length
              });
            })
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'clearAutomaticHighlights') {
        clearAutomaticHighlightsAndPersist()
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message }));
        return true;
    } else if (request.action === 'clearManualAnnotations') {
        const cleared = request.completed === true &&
            clearManualAnnotationsAfterBackground(request.completionType);
        sendResponse({
            success: cleared,
            error: cleared ? undefined : '请先完成 ANNOTATION_CLEAR_DOCUMENT'
        });
    } else if (request.action === 'disableManualAnnotations') {
        disableManualAnnotationUi();
        sendResponse({ success: true });
    } else if (request.action === 'reinitializeManualAnnotations') {
        reinitializeManualAnnotationsAfterCommit(request.expectedIdentity)
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message }));
    } else if (request.action === 'applyHighlight') {
        try {
            const allowedParagraphIds = selectedArticleAnalysisParagraphIds();
            const semanticAnalysisScope = currentNativePdfSemanticAnalysisScope();
            const counts = highlighter.applyHighlight(
                request.categories,
                request.mode,
                {
                    allowedParagraphIds,
                    semanticAnalysisScope,
                    analysisModeId: request.analysisModeId
                }
            );
            lastRegexHighlightRequest = {
                categories: request.categories,
                mode: request.mode === 'sentence' ? 'sentence' : 'word',
                analysisModeId: String(request.analysisModeId || 'regex-default')
            };
            scheduleCurrentArticleArchiveSave();
            sendResponse({ success: true, counts: counts,
                highlightDiagnostics: { ...highlighter.lastNativePdfHighlightDiagnostics } });
        } catch (error) {
            console.error('应用高亮失败:', error);
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'clearHighlight') {
        try {
            highlighter.clearHighlight();
            sendResponse({ success: true });
        } catch (error) {
            console.error('清除高亮失败:', error);
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'getMatchCounts') {
        try {
            const allowedParagraphIds = selectedArticleAnalysisParagraphIds();
            const semanticAnalysisScope = currentNativePdfSemanticAnalysisScope();
            const counts = highlighter.getMatchCounts(request.rules, {
                allowedParagraphIds,
                semanticAnalysisScope
            });
            sendResponse({ success: true, counts: counts,
                highlightDiagnostics: { ...highlighter.lastNativePdfHighlightDiagnostics } });
        } catch (error) {
            console.error('获取匹配计数失败:', error);
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'extractArticleForLLM') {
        try {
            const paragraphs = extractArticleWithTrace('popup_document_prepare', {
                forceRefresh: request.forceRefresh === true
            })
                .map(({ sourceIndex, ...paragraph }) => paragraph);
            sendResponse({
                success: true,
                document: {
                    title: document.title,
                    paragraphs
                }
            });
        } catch (error) {
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'applyLlmConfidenceThreshold') {
        if (!lastLlmAnalysis) {
            sendResponse({ success: true, applied: false, reason: 'NO_ANALYSIS_ON_PAGE' });
        } else {
            const rendered = renderLlmAnalysis(
                lastLlmAnalysis.rawAnalysis,
                lastLlmAnalysis.paragraphs,
                request.threshold,
                lastLlmAnalysis.extractionDiagnostics
            );
            sendResponse({
                success: true,
                applied: true,
                highlightedCount: rendered.highlightedCount,
                hiddenConfidenceCount: rendered.hiddenCount,
                counts: rendered.counts,
                familyCounts: rendered.familyCounts,
                presentationModeCounts: rendered.presentationModeCounts,
                threshold: rendered.threshold
            });
        }
    } else if (request.action === 'applyLlmPresentation') {
        const allowedFamilies = new Set(Object.keys(SciLLM.DISPLAY_FAMILIES || {}));
        llmPresentationState = {
            density: SciLLM.normalizePresentationDensity?.(request.density || 'all') || 'all',
            hiddenFamilyIds: [...new Set(
                (Array.isArray(request.hiddenFamilyIds) ? request.hiddenFamilyIds : [])
                    .map(String)
                    .filter(familyId => allowedFamilies.has(familyId))
            )],
            language: String(request.language || '').toLowerCase().startsWith('en')
                ? 'en' : 'zh-CN'
        };
        if (!lastLlmAnalysis) {
            sendResponse({
                success: true,
                applied: false,
                reason: 'NO_ANALYSIS_ON_PAGE',
                presentation: { ...llmPresentationState }
            });
        } else {
            const rendered = renderLlmAnalysis(
                lastLlmAnalysis.rawAnalysis,
                lastLlmAnalysis.paragraphs,
                lastLlmAnalysis.threshold,
                lastLlmAnalysis.extractionDiagnostics
            );
            sendResponse({
                success: true,
                applied: true,
                highlightedCount: rendered.highlightedCount,
                hiddenPresentationCount: rendered.hiddenPresentationCount,
                counts: rendered.counts,
                familyCounts: rendered.familyCounts,
                presentationModeCounts: rendered.presentationModeCounts,
                presentation: { ...llmPresentationState }
            });
        }
    } else if (request.action === 'getLlmDiagnostics') {
        try {
            if (!lastLlmDiagnostics) {
                lastLlmDiagnostics = {
                    extraction: diagnoseArticleWithTrace('popup_diagnostics'),
                    stage: 'ready'
                };
            }
            sendResponse({ success: true, diagnostics: lastLlmDiagnostics });
        } catch (error) {
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'buildAdapterDiagnosticBundle') {
        try {
            const bundle = SciLLM.buildAdapterDiagnosticBundle(document, {
                extensionVersion: chrome.runtime.getManifest?.().version || '',
                contentRevision: document.documentElement.dataset.sciLlmContentRevision || '',
                trace: extractionTrace.snapshot(),
                extraction: {
                    available: Boolean(lastLlmDiagnostics || lastSuccessfulExtraction),
                    diagnostics: lastLlmDiagnostics?.extraction || null,
                    lastStage: lastLlmDiagnostics?.stage || '',
                    paragraphs: serializeLastExtractionForDiagnostic()
                },
                structure: lastSuccessfulStructure
            });
            sendResponse({ success: true, bundle });
        } catch (error) {
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'exportPublisherDiagnostic') {
        try {
            const report = SciLLM.buildPublisherDiagnostic(document, {
                extensionVersion: chrome.runtime.getManifest?.().version || '',
                contentRevision: document.documentElement.dataset.sciLlmContentRevision || '',
                trace: extractionTrace.snapshot(),
                extraction: {
                    available: Boolean(lastLlmDiagnostics || lastSuccessfulExtraction),
                    diagnostics: lastLlmDiagnostics?.extraction || null,
                    lastStage: lastLlmDiagnostics?.stage || '',
                    paragraphs: serializeLastExtractionForDiagnostic()
                },
                structure: lastSuccessfulStructure
            });
            const filename = SciLLM.downloadPublisherDiagnostic(report, document);
            sendResponse({
                success: true,
                filename,
                candidateCount: report.candidates?.length || 0,
                publisherFamily: report.publisher?.family || 'generic'
            });
        } catch (error) {
            sendResponse({ success: false, error: error.message });
        }
    } else if (request.action === 'analyzeArticleWithLLM') {
        analyzeArticleWithLLM({
            auto: false,
            documentId: request.documentId,
            documentHash: request.documentHash,
            readingViewId: request.readingViewId
        })
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'controlLlmOperation') {
        controlLlmOperation(
            request.scope === 'figure' ? 'figure' : 'highlight',
            String(request.command || '')
        )
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'analyzeFiguresWithLLM') {
        analyzeFiguresWithLLM({ analysisDepth: request.analysisDepth })
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'importSupplementalFigureDraft') {
        importSupplementalFigureDraft(request)
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'SUPPLEMENTAL_IMPORT_FAILED',
                ...(error.savedDraft ? { savedDraft: error.savedDraft } : {})
            }));
    } else if (request.action === 'updateSupplementalFigureDraft') {
        updateImportedSupplementalFigureDraft(request)
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'SUPPLEMENTAL_UPDATE_FAILED'
            }));
    } else if (request.action === 'deleteSupplementalFigure') {
        deleteImportedSupplementalFigure(request)
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'SUPPLEMENTAL_DELETE_FAILED'
            }));
    } else if (request.action === 'analyzeSingleFigureWithLLM') {
        analyzeSingleFigureWithLLM(String(request.figureId || ''), {
            forceRefresh: request.forceRefresh === true
        })
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'analyzeSingleFigurePanelWithLLM') {
        analyzeSingleFigurePanelWithLLM(
            String(request.figureId || ''),
            String(request.panelId || ''),
            { forceRefresh: request.forceRefresh === true }
        )
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'analyzeSingleFigureDeepWithLLM') {
        const figureId = String(request.figureId || '');
        runIdempotentFigureRecoveryAction(
            request,
            'deep_rerun',
            () => analyzeSingleFigureDeep(figureId, {
                expectedFigureInputHash: String(request.expectedFigureInputHash || '')
            })
        )
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'retryMissingFigurePanelsWithLLM') {
        runIdempotentFigureRecoveryAction(
            request,
            'missing_panels',
            () => retryMissingFigurePanelsWithLLM(request)
        )
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: error.message,
                code: error.code || 'FIGURE_PANEL_RETRY_FAILED'
            }));
    } else if (request.action === 'askFigurePanelWithLLM') {
        askFigurePanelWithLLM(
            String(request.figureId || ''),
            String(request.panelId || ''),
            Array.isArray(request.topics) ? request.topics : [],
            String(request.customQuestion || ''),
            String(request.historyLabel || '')
        )
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'highlightArticleMatchesWithLLM') {
        askArticleWithLLM(
            String(request.question || ''),
            String(request.profileId || ''),
            {
                intent: 'highlight',
                categoryId: String(request.categoryId || 'semantic_match'),
                categoryName: String(request.categoryName || ''),
                highlightColor: String(request.highlightColor || ''),
                contextScope: request.contextScope
            }
        )
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'askArticleWithLLM') {
        askArticleWithLLM(
            String(request.question || ''),
            String(request.profileId || ''),
            {
                contextScope: request.contextScope,
                webSearch: request.webSearch
            }
        )
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'cancelArticleChatWithLLM') {
        cancelArticleChatWithLLM()
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'deleteArticleChatTurn') {
        removeArticleChatTurn(String(request.turnId || ''))
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'deleteArticleChatAnswer') {
        deleteArticleChatAnswer(String(request.turnId || ''))
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'deleteQueuedArticleChatTurn') {
        removeArticleChatTurn(
            String(request.turnId || ''), { queuedOnly: true }
        )
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'regenerateArticleChatTurn') {
        regenerateArticleChatTurn(
            String(request.turnId || ''), String(request.profileId || '')
        )
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'clearArticleChat') {
        clearArticleChat()
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'showFigureOriginalImage') {
        showFigureOriginalImage(String(request.figureId || ''), {
            documentHash: request.documentHash,
            documentGeneration: request.documentGeneration,
            panelId: request.panelId,
            sourcePage: request.sourcePage
        })
            .then(sendResponse)
            .catch(error => sendResponse({
                success: false,
                code: String(error?.code || 'FIGURE_VIEWER_FAILED'),
                message: String(error?.message || 'Figure 高清原图打开失败')
            }));
    } else if (request.action === 'getFigureOriginalImageState') {
        sendResponse(getFigureImageViewerState());
    } else if (request.action === 'navigateFigureOriginalImage') {
        navigateFigureImageViewer(
            String(request.direction || ''),
            Number(request.figureNumber) || 0
        )
            .then(sendResponse)
            .catch(error => sendResponse({
                success: false,
                code: String(error?.code || 'FIGURE_VIEWER_NAVIGATION_FAILED'),
                message: String(error?.message || 'Figure 高清原图切换失败')
            }));
    } else if (request.action === 'closeFigureOriginalImage') {
        sendResponse(closeFigureImageViewer());
    } else if (request.action === 'cancelCrossFigureLogicWithLLM') {
        cancelCrossFigureLogicWithLLM(request)
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: 'MECHANISM_CANCEL_FAILED',
                code: ['MECHANISM_OPERATION_STALE', 'MECHANISM_CANCEL_FAILED']
                    .includes(error?.code) ? error.code : 'MECHANISM_CANCEL_FAILED'
            }));
    } else if (request.action === 'analyzeCrossFigureLogicWithLLM') {
        analyzeCrossFigureLogicWithLLM(request)
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false,
                error: 'MECHANISM_GENERATION_FAILED',
                code: [
                    'MECHANISM_REQUEST_INVALID',
                    'CROSS_FIGURE_LOGIC_REQUIRES_TWO_MAIN_FIGURES'
                ].includes(error?.code) ? error.code : 'MECHANISM_GENERATION_FAILED'
            }));
    } else if (request.action === 'analyzeResearchLogicWithLLM') {
        analyzePaperMetaWithLLM('research_logic', {
            forceRefresh: request.forceRefresh === true
        })
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'analyzePaperInnovationWithLLM') {
        analyzePaperMetaWithLLM('innovation', {
            forceRefresh: request.forceRefresh === true
        })
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'analyzePaperLimitationsWithLLM') {
        analyzePaperMetaWithLLM('limitations', {
            forceRefresh: request.forceRefresh === true
        })
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    } else if (request.action === 'autofillLiteratureNoteWithLLM') {
        autofillLiteratureNoteWithLLM(request.template, {
            forceRefresh: request.forceRefresh === true,
            operationId: request.operationId
        })
            .then(result => sendResponse(result))
            .catch(error => sendResponse({
                success: false, error: error.message, code: error.code
            }));
    } else if (request.action === 'analyzeReviewParagraphWithLLM') {
        const target = {
            paragraphId: String(request.paragraphId || '').trim(),
            sourceKey: String(request.sourceKey || '').trim(),
            navigationRevision: request.navigationRevision,
            documentId: request.documentId,
            documentHash: request.documentHash
        };
        analyzeReviewParagraphWithLLM(target)
            .then(result => sendResponse({
                ...result,
                paragraphSummary: result.paragraphSummary ||
                    standaloneReviewParagraphSummaries.get(target.paragraphId) || null
            }))
            .catch(error => sendResponse({
                success: false, error: error.message, code: error.code
            }));
    } else if (request.action === 'analyzeReviewOutlineWithLLM') {
        analyzeReviewOutlineWithLLM({
            forceRefresh: request.forceRefresh === true,
            documentId: request.documentId,
            documentHash: request.documentHash,
            scopeSectionIds: Array.isArray(request.scopeSectionIds)
                ? request.scopeSectionIds : [],
            scopeSelectionProvided: request.scopeSelectionProvided === true
        })
            .then(result => sendResponse(result))
            .catch(error => sendResponse({ success: false, error: error.message, code: error.code }));
    }
    
    return true; // 保持消息通道开放
});

// The injector owns the document-wide claim until all scripts finish loading.
if (globalThis.__brevessDeferArticlePreindex !== true) {
    scheduleArticlePreindex('content-script-ready');
}
delete globalThis.__brevessDeferArticlePreindex;

console.log('Brevess 已加载');
